  "steps": [
    {
      "step": 1,
      "instruction": "Ikabit ang wiper (gitnang pin) ng potentiometer sa Analog Pin A0, ang kaliwang pin sa 5V, at ang kanang pin sa GND.",
      "why": "Gumagawa ito ng variable voltage divider mula 0V hanggang 5V.",
      "check": "Naka-seat nang maayos ang tatlong terminals sa magkakahiwalay na columns."
    },
    {
      "step": 2,
      "instruction": "Ikabit ang LED anode sa 220 ohm resistor papuntang Digital Pin 13, at ang cathode sa GND.",
      "why": "Proteksyon sa LED laban sa labis na kuryente mula sa Pin 13.",
      "check": "Tamang polarity ng LED: mahabang paa sa resistor, maikling paa sa GND."
